-- DD-20260917-OBS，只读核验；未执行。必须先完成本模块OBS-02。
SELECT table_name,COUNT(*) AS column_count FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('lab_observation_mapping','lab_observation_receipt','lab_observation_conflict','lab_observation','lab_observation_association','lab_observation_current','lab_observation_outbox','lab_observation_monitor') GROUP BY table_name ORDER BY table_name;
SELECT table_name,index_name,non_unique,seq_in_index,column_name FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('lab_observation_mapping','lab_observation_receipt','lab_observation_conflict','lab_observation','lab_observation_association','lab_observation_current','lab_observation_outbox','lab_observation_monitor') ORDER BY table_name,index_name,seq_in_index;
SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name IN ('lab_observation_mapping','lab_observation_receipt','lab_observation_conflict','lab_observation','lab_observation_association','lab_observation_current','lab_observation_outbox','lab_observation_monitor') ORDER BY table_name,constraint_name;
-- 下列异常查询预期0行；不自动修复/删除。
SELECT o.observation_id FROM lab_observation o LEFT JOIN lab_observation_receipt r ON r.receipt_id=o.receipt_id WHERE r.receipt_id IS NULL;
SELECT o.observation_id FROM lab_observation o LEFT JOIN lab_observation_mapping m ON m.mapping_id=o.mapping_id WHERE o.validation_state='VALID' AND (m.mapping_id IS NULL OR o.item_id<>m.item_id);
SELECT a.association_id FROM lab_observation_association a LEFT JOIN lab_observation o ON o.observation_id=a.observation_id WHERE o.observation_id IS NULL;
SELECT c.device_kind,c.device_id,c.channel_code,c.item_id FROM lab_observation_current c LEFT JOIN lab_observation o ON o.observation_id=c.current_observation_id LEFT JOIN lab_observation_receipt r ON r.receipt_id=o.receipt_id WHERE o.observation_id IS NULL OR o.validation_state<>'VALID' OR c.item_id<>o.item_id OR c.device_kind<>r.device_kind OR c.device_id<>r.device_id OR c.channel_code<>r.channel_code;
SELECT c.device_id,c.item_id FROM lab_observation_current c JOIN lab_observation o ON o.observation_id=c.last_good_observation_id WHERE o.quality<>'GOOD' OR o.validation_state<>'VALID';
SELECT a.mapping_id,b.mapping_id AS overlaps_with FROM lab_observation_mapping a JOIN lab_observation_mapping b ON a.device_kind=b.device_kind AND a.device_id=b.device_id AND a.channel_code=b.channel_code AND a.raw_metric_code=b.raw_metric_code AND a.mapping_id<b.mapping_id AND (a.effective_to IS NULL OR b.effective_from<a.effective_to) AND (b.effective_to IS NULL OR a.effective_from<b.effective_to);

